    int8_t target_player;   // +0xC2 player attacked (-1 none)
    uint8_t pad_c3[0x5];
    int32_t w0c0;   // +0xC8 per-kind work (Hangedman: dive angle; Murrer groups: a float)
    uint8_t pad_cc[0x4];
    int32_t part_root;   // +0xD0 root of the body part tree (body_init)
