    int32_t w2f8;   // +0x300 per-kind work
    uint8_t pad_304[0x8];
    int32_t ai_at_once;   // +0x30C 1 = start the AI at once (kind000_enemy_spawn), 0 = wait (enemy_ai)
    int32_t one_hit_kill;   // +0x310 nonzero: any hit (flags bit 8) kills
