// one enemy spawn record of an ENTB list (same in EVTALL.RBH on the PC)
struct SpawnRecord {
    uint32_t kind;   // +0x0 object kind (kind table 0xAFDE0: the new object's routine)
    uint32_t flags;   // +0x4 the object's flags (| 1 = shootable); bit 31 seen in the scripts
    float pos[3];   // +0x8 world position (placement mode 0) or a position relative to the camera (modes 1 / 2, throu
    int32_t ang[3];   // +0x14 angles x / y / z -> obj ang (y = the facing)
    uint16_t place_mode;   // +0x20 & 3: 0 = pos as given, 1 / 2 = relative to the camera (evt_ENTB)
    int16_t life;   // +0x22 the enemy's hit points: copied to obj +0x70 (life) and +0x72; enemy_check_death subtracts 
    uint8_t type;   // +0x24 creature type -> obj +0xCC
    uint8_t action;   // +0x25 action code -> obj +0x64
    uint16_t id_flags;   // +0x26 high half of the record ID: behaviour flags (open)
};
static_assert(sizeof(SpawnRecord) == 0x28);

// an attack position: where one enemy may stand and attack (attack_slots)
struct AttackSlot {
    uint8_t taken;   // +0x0 1 = held by an enemy
    uint8_t pad_1[0x3];
    Addr<Obj> holder;   // +0x4 the enemy holding it
    float pos[3];   // +0x8 position (0 / 1: camera + offsets each frame; y unused there)
};
static_assert(sizeof(AttackSlot) == 0x14);

// one entry of a type's motion list (by sub-state): the motion and its forward speed
struct MotionStep {
    int32_t motion;   // +0x0 motion number (MO_ table)
    float speed;   // +0x4 forward speed per frame while it plays (0 = none)
};
static_assert(sizeof(MotionStep) == 0x8);

// one attack of a type / action (enemy_ai: attack record 0xC6F10[type][action][attack])
struct EnemyAttack {
    int32_t motion;   // +0x0 the attack motion (in reach)
    int32_t lunge_motion;   // +0x4 the lunge motion (beyond the reach)
    float lunge_speed;   // +0x8 speed of the lunge
    float reach;   // +0xC distance (target z) below which it attacks at once
    int32_t hit_frame;   // +0x10 motion frame at which player_hit happens
    int8_t hit_side;   // +0x14 side passed to player_hit (the screen shake direction)
    uint8_t needs_parts;   // +0x15 parts_lost bits that cancel the hit (an arm it lost)
    uint8_t pad_16[0x2];
};
static_assert(sizeof(EnemyAttack) == 0x18);

