// layout traits of the arcade (A)
struct A {
    static constexpr bool pc = false;
    using Obj = a::Obj;
    using PlayerTask = a::PlayerTask;
    using Player = a::Player;
    using GunInput = a::GunInput;
    using BodyPart = a::BodyPart;
    using PartRole = a::PartRole;
    using DepthEntry = a::DepthEntry;
    using ShotCandidate = a::ShotCandidate;
    using ShotResult = a::ShotResult;
    using ShotRay = a::ShotRay;
    using Enemy = a::Enemy;
    using CameraRecord = a::CameraRecord;
    using SpawnRecord = a::SpawnRecord;
    using AttackSlot = a::AttackSlot;
    using MotionStep = a::MotionStep;
    using EnemyAttack = a::EnemyAttack;
    using G = a::G;
    using F = a::F;
    // the version's offset of a field given by its arcade offset (unnamed fields; named ones: the structs)
    template <class S> static constexpr uint32_t off(uint32_t a);
};
template <> constexpr uint32_t A::off<a::Obj>(uint32_t a) { return a; }
template <> constexpr uint32_t A::off<a::PlayerTask>(uint32_t a) { return a; }
template <> constexpr uint32_t A::off<a::Player>(uint32_t a) { return a; }
template <> constexpr uint32_t A::off<a::GunInput>(uint32_t a) { return a; }
template <> constexpr uint32_t A::off<a::BodyPart>(uint32_t a) { return a; }
template <> constexpr uint32_t A::off<a::PartRole>(uint32_t a) { return a; }
template <> constexpr uint32_t A::off<a::DepthEntry>(uint32_t a) { return a; }
template <> constexpr uint32_t A::off<a::ShotCandidate>(uint32_t a) { return a; }
