// layout traits of the PC port (PA / PM)
struct Pc {
    static constexpr bool pc = true;
    using Obj = pc::Obj;
    using PlayerTask = pc::PlayerTask;
    using Player = pc::Player;
    using GunInput = pc::GunInput;
    using BodyPart = pc::BodyPart;
    using PartRole = pc::PartRole;
    using DepthEntry = pc::DepthEntry;
    using ShotCandidate = pc::ShotCandidate;
    using ShotResult = pc::ShotResult;
    using ShotRay = pc::ShotRay;
    using Enemy = pc::Enemy;
    using CameraRecord = pc::CameraRecord;
    using SpawnRecord = pc::SpawnRecord;
    using AttackSlot = pc::AttackSlot;
    using MotionStep = pc::MotionStep;
    using EnemyAttack = pc::EnemyAttack;
    using G = pc::G;
    using F = pc::F;
    // the version's offset of a field given by its arcade offset (unnamed fields; named ones: the structs)
    template <class S> static constexpr uint32_t off(uint32_t a);
};
template <> constexpr uint32_t Pc::off<pc::Obj>(uint32_t a) { return a >= 0x10 ? a + 0x8 : a; }
template <> constexpr uint32_t Pc::off<pc::PlayerTask>(uint32_t a) { return a >= 0x10 ? a + 0x8 : a; }
template <> constexpr uint32_t Pc::off<pc::Player>(uint32_t a) { return a; }
