template <> constexpr uint32_t Pc::off<pc::ShotRay>(uint32_t a) { return a; }
template <> constexpr uint32_t Pc::off<pc::Enemy>(uint32_t a) { return a >= 0x10 ? a + 0x8 : a; }
template <> constexpr uint32_t Pc::off<pc::CameraRecord>(uint32_t a) { return a; }
template <> constexpr uint32_t Pc::off<pc::SpawnRecord>(uint32_t a) { return a; }
